import React, { useEffect, useMemo, useRef, useState } from 'react';
import { AlertTriangle, Archive, ArrowDownUp, BarChart3, Building2, Check, CheckCircle2, Crosshair, Download, FileText, MapPin, PackageCheck, Pencil, Plus, Search, ShieldAlert, SlidersHorizontal, Trash2, UserRound, Users, XCircle } from 'lucide-react';
import { ApiClient } from '../../api/client';
import { geocodeAddress, loadGoogleMaps } from '../../lib/googleMaps';
import { useApp } from '../../context/AppContext';
import { Button, Card, MetricCard } from '../ui/DesignSystem';

const fieldClass = 'mt-1 w-full rounded-xl border border-slate-200 bg-white p-3 text-sm outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 dark:border-slate-700 dark:bg-slate-950';
const errorBox = (message: string) => message ? <div role="alert" className="flex items-start gap-2 rounded-xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-700 dark:border-rose-900 dark:bg-rose-950/30 dark:text-rose-300"><XCircle className="mt-0.5 h-4 w-4 shrink-0" />{message}</div> : null;
const title = (icon: React.ReactNode, heading: string, description: string, onRefresh?: () => void) => <div className="flex flex-wrap items-start justify-between gap-4"><div><h2 className="flex items-center gap-2 text-2xl font-black tracking-tight">{icon}{heading}</h2><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">{description}</p></div>{onRefresh && <Button variant="secondary" size="sm" onClick={onRefresh}>Actualizar</Button>}</div>;
const inputNumber = (value: unknown, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;

type AddressTarget = { address: string; city: string; province: string; country: string; postalCode: string; latitude: number | null; longitude: number | null };

function usePlacesAutocomplete(ref: React.RefObject<HTMLInputElement | null>, apiKey: string, onPlace: (target: Partial<AddressTarget>) => void) {
  useEffect(() => {
    if (!apiKey || !ref.current) return;
    let disposed = false;
    let listener: any;
    void loadGoogleMaps(apiKey).then(() => {
      if (disposed || !ref.current || !window.google?.maps?.places?.Autocomplete) return;
      const autocomplete = new window.google.maps.places.Autocomplete(ref.current, { fields: ['formatted_address', 'address_components', 'geometry'], componentRestrictions: { country: ['do'] } });
      listener = autocomplete.addListener('place_changed', () => {
        const place = autocomplete.getPlace();
        const components = Object.fromEntries((place.address_components || []).flatMap((component: any) => component.types.map((type: string) => [type, component.long_name])));
        onPlace({ address: String(place.formatted_address || ref.current?.value || ''), city: String(components.locality || components.administrative_area_level_2 || ''), province: String(components.administrative_area_level_1 || ''), country: String(components.country === 'República Dominicana' ? 'DO' : components.country || 'DO').slice(0, 2).toUpperCase(), postalCode: String(components.postal_code || ''), latitude: place.geometry?.location ? Number(place.geometry.location.lat()) : null, longitude: place.geometry?.location ? Number(place.geometry.location.lng()) : null });
      });
    }).catch(() => undefined);
    return () => { disposed = true; listener?.remove?.(); };
  }, [apiKey, ref, onPlace]);
}

async function resolveMapKey() {
  const result = await ApiClient.getPublicMapConfiguration();
  return result.success && result.configured && result.apiKey ? result.apiKey : '';
}

const MapPreview: React.FC<{ latitude: number | null | undefined; longitude: number | null | undefined; label: string }> = ({ latitude, longitude, label }) => latitude == null || longitude == null ? <div className="flex min-h-40 items-center justify-center rounded-2xl border border-dashed border-slate-300 bg-slate-50 p-5 text-center text-xs text-slate-500 dark:border-slate-700 dark:bg-slate-950">Busca una dirección o usa tu ubicación para ver la vista previa del mapa.</div> : <div className="overflow-hidden rounded-2xl border border-slate-200 dark:border-slate-700"><iframe title={`Vista previa de ${label}`} className="h-48 w-full" loading="lazy" src={`https://www.google.com/maps?q=${encodeURIComponent(`${latitude},${longitude}`)}&z=16&output=embed`} /><p className="border-t border-slate-200 bg-white px-3 py-2 text-[11px] text-slate-500 dark:border-slate-700 dark:bg-slate-900">{latitude.toFixed(6)}, {longitude.toFixed(6)} · {label}</p></div>;

type ScanRow = { id: string; trackingNumber: string; status: 'queued' | 'processing' | 'success' | 'duplicate' | 'error'; currentStatus?: string; nextStatus?: string; processedAt?: string; processedBy?: string; message?: string };

export const ProductionMassScanPanel: React.FC = () => {
  const { addToast } = useApp();
  const inputRef = useRef<HTMLInputElement>(null);
  const [branches, setBranches] = useState<any[]>([]); const [branchId, setBranchId] = useState(''); const [action, setAction] = useState<'receive' | 'store' | 'dispatch'>('receive'); const [location, setLocation] = useState(''); const [code, setCode] = useState(''); const [bulkText, setBulkText] = useState(''); const [rows, setRows] = useState<ScanRow[]>([]); const [processing, setProcessing] = useState(false); const [error, setError] = useState(''); const [finished, setFinished] = useState(false);
  useEffect(() => { void ApiClient.getBranches().then(result => { if (result.success) { setBranches(result.branches || []); setBranchId(result.branches?.[0]?.id || ''); } else setError(result.error); }); }, []);
  const addCodes = (value: string) => { const codes = value.split(/[\n,;\s]+/).map(item => item.trim()).filter(Boolean); if (!codes.length) return; setRows(current => { const known = new Set(current.map(item => item.trackingNumber.toLowerCase())); const next = [...current]; codes.forEach(trackingNumber => { const key = trackingNumber.toLowerCase(); if (known.has(key)) next.push({ id: crypto.randomUUID(), trackingNumber, status: 'duplicate', message: 'Duplicado en esta sesión' }); else { known.add(key); next.push({ id: crypto.randomUUID(), trackingNumber, status: 'queued' }); } }); return next; }); setCode(''); setFinished(false); window.navigator.vibrate?.(45); inputRef.current?.focus(); };
  const totals = useMemo(() => ({ total: rows.length, queued: rows.filter(row => row.status === 'queued').length, success: rows.filter(row => row.status === 'success').length, duplicate: rows.filter(row => row.status === 'duplicate').length, errors: rows.filter(row => row.status === 'error').length }), [rows]);
  const process = async () => { const pending = rows.filter(row => row.status === 'queued'); if (!branchId || !pending.length) return; if (pending.length >= 10 && !window.confirm(`Vas a procesar ${pending.length} paquetes. El servidor validará cada guía. ¿Continuar?`)) return; setProcessing(true); setError(''); for (const row of pending) { setRows(current => current.map(item => item.id === row.id ? { ...item, status: 'processing' } : item)); const result = await ApiClient.scanBranchShipment(branchId, { trackingNumber: row.trackingNumber, action, location: location.trim() || undefined }, `bulk-scan-${branchId}-${row.trackingNumber}-${crypto.randomUUID()}`); if (result.success) { setRows(current => current.map(item => item.id === row.id ? { ...item, status: 'success', currentStatus: result.previousStatus, nextStatus: result.status, processedAt: result.processedAt, processedBy: result.processedBy } : item)); } else { setRows(current => current.map(item => item.id === row.id ? { ...item, status: 'error', message: result.error } : item)); } } setProcessing(false); setFinished(true); addToast('success', 'Sesión de escaneo procesada', 'El resumen refleja exclusivamente las respuestas persistidas por el servidor.'); };
  const actionLabel = action === 'receive' ? 'Recibir en sucursal' : action === 'store' ? 'Ubicar en almacén' : 'Despachar a ruta';
  return <div className="space-y-6">{title(<PackageCheck className="h-7 w-7 text-indigo-600" />, 'Escaneo masivo guiado', 'Diseñado para pistola lectora, tablet y teclado. Primero prepara la operación, luego carga una cola visible y finalmente confirma el lote contra el motor real de sucursales.')}{errorBox(error)}<div className="grid gap-3 sm:grid-cols-4"><MetricCard title="En sesión" value={totals.total} subtitle="Leídos o añadidos" icon={<BarChart3 className="h-5 w-5" />} accent="indigo" /><MetricCard title="Exitosos" value={totals.success} subtitle="Confirmados por API" icon={<CheckCircle2 className="h-5 w-5" />} accent="emerald" /><MetricCard title="Duplicados" value={totals.duplicate} subtitle="No se procesan dos veces" icon={<ArrowDownUp className="h-5 w-5" />} accent="amber" /><MetricCard title="Errores" value={totals.errors} subtitle="Requieren revisión" icon={<AlertTriangle className="h-5 w-5" />} accent="rose" /></div><div className="grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><Card className="space-y-5"><div className="flex items-center gap-3"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-indigo-600 text-sm font-black text-white">1</span><div><h3 className="font-bold">Prepara la operación</h3><p className="text-xs text-slate-500">La acción se aplicará a cada guía de la cola.</p></div></div><label className="block text-xs font-bold">Sucursal<select value={branchId} onChange={event => setBranchId(event.target.value)} className={fieldClass}>{branches.map(branch => <option key={branch.id} value={branch.id}>{branch.name} · {branch.code}</option>)}</select></label><label className="block text-xs font-bold">Paso operativo<select value={action} onChange={event => setAction(event.target.value as typeof action)} className={fieldClass}><option value="receive">Recibir en sucursal</option><option value="store">Ubicar en almacén</option><option value="dispatch">Despachar a ruta</option></select></label><label className="block text-xs font-bold">Rack / bin <span className="font-normal text-slate-400">(si aplica)</span><input value={location} onChange={event => setLocation(event.target.value)} className={fieldClass} placeholder="Ej. RACK-A-04" /></label><div className="rounded-xl border border-indigo-100 bg-indigo-50 p-4 text-xs leading-5 text-indigo-800 dark:border-indigo-900 dark:bg-indigo-950/30 dark:text-indigo-200"><b>{actionLabel}</b><br />La guía debe existir y cumplir la transición permitida. Una lectura desconocida no crea ningún paquete.</div></Card><Card className="space-y-5"><div className="flex items-center gap-3"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-indigo-600 text-sm font-black text-white">2</span><div><h3 className="font-bold">Escanea continuamente</h3><p className="text-xs text-slate-500">Una pistola USB normalmente escribe aquí y envía Enter.</p></div></div><form onSubmit={event => { event.preventDefault(); addCodes(code); }} className="flex gap-2"><input ref={inputRef} autoFocus value={code} onChange={event => setCode(event.target.value)} className={`${fieldClass} mt-0 font-mono`} placeholder="Escanea o escribe una guía" aria-label="Guía para escaneo" /><Button type="submit" icon={<Plus className="h-4 w-4" />}>Añadir</Button></form><div className="flex items-end gap-2"><label className="block flex-1 text-xs font-bold">Carga varias guías<textarea value={bulkText} onChange={event => setBulkText(event.target.value)} className={`${fieldClass} min-h-24 font-mono`} placeholder="Una guía por línea, coma o espacio" /></label><Button type="button" variant="secondary" onClick={() => { addCodes(bulkText); setBulkText(''); }} disabled={!bulkText.trim()}>Añadir lote</Button></div><div className="flex flex-wrap items-center justify-between gap-2 text-xs text-slate-500"><span>Cola lista: <b className="text-slate-900 dark:text-white">{totals.queued}</b></span><button type="button" className="font-bold text-rose-600 disabled:opacity-40" disabled={!rows.length || processing} onClick={() => setRows(current => current.filter(row => row.status !== 'queued' && row.status !== 'duplicate'))}>Quitar pendientes</button></div><Button className="w-full" disabled={processing || !totals.queued || !branchId} onClick={() => void process()}>{processing ? 'Procesando guía por guía…' : `Confirmar lote (${totals.queued})`}</Button></Card></div><Card className="overflow-hidden p-0"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-200 p-4 dark:border-slate-800"><div><h3 className="font-bold">3. Historial de la sesión</h3><p className="mt-1 text-xs text-slate-500">Puedes corregir o retirar pendientes antes de confirmar. Después queda el resultado real del servidor.</p></div>{finished && <span className="rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-700">Resumen listo</span>}</div>{!rows.length ? <div className="p-10 text-center text-sm text-slate-500"><Archive className="mx-auto h-8 w-8 text-slate-300" /><p className="mt-3">No hay guías en la sesión.</p></div> : <div className="overflow-x-auto"><table className="min-w-full text-left text-xs"><thead className="bg-slate-50 text-[10px] uppercase text-slate-500 dark:bg-slate-950"><tr><th className="px-4 py-3">Guía</th><th className="px-4 py-3">Cliente</th><th className="px-4 py-3">Sucursal</th><th className="px-4 py-3">Estado actual</th><th className="px-4 py-3">Nuevo estado</th><th className="px-4 py-3">Fecha / usuario</th><th className="px-4 py-3">Resultado</th><th /></tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-800">{rows.map(row => <tr key={row.id}><td className="px-4 py-3 font-mono font-bold">{row.trackingNumber}</td><td className="px-4 py-3">{(row as any).clientName || '—'}</td><td className="px-4 py-3">{(row as any).branchName || '—'}</td><td className="px-4 py-3">{row.currentStatus || 'Pendiente de validar'}</td><td className="px-4 py-3">{row.nextStatus || '—'}</td><td className="px-4 py-3">{row.processedAt ? <>{new Date(row.processedAt).toLocaleString()}<br /><span className="text-slate-500">{row.processedBy || 'Usuario autenticado'}</span></> : '—'}</td><td className="px-4 py-3">{row.status === 'success' ? <span className="font-bold text-emerald-700">Confirmado</span> : row.status === 'duplicate' ? <span className="font-bold text-amber-700">Duplicado</span> : row.status === 'error' ? <span className="font-bold text-rose-700" title={row.message}>Error</span> : row.status === 'processing' ? 'Procesando…' : 'En cola'}</td><td className="px-4 py-3 text-right">{(row.status === 'queued' || row.status === 'duplicate') && <button type="button" className="text-rose-600 hover:underline" onClick={() => setRows(current => current.filter(item => item.id !== row.id))}>Quitar</button>}</td></tr>)}</tbody></table></div>}</Card></div>;
};

type BranchForm = { code: string; name: string; city: string; address: string; country: string; province: string; sector: string; postalCode: string; phone: string; whatsapp: string; email: string; managerName: string; managerPhone: string; managerEmail: string; branchType: string; businessHours: string; isHub: boolean; latitude: number | null; longitude: number | null; logo?: string | null };
const blankBranch = (): BranchForm => ({ code: '', name: '', city: '', address: '', country: 'DO', province: '', sector: '', postalCode: '', phone: '', whatsapp: '', email: '', managerName: '', managerPhone: '', managerEmail: '', branchType: 'branch', businessHours: 'Lun-Vie 8:00-18:00', isHub: false, latitude: null, longitude: null, logo: null });

export const ProductionBranchesAdmin: React.FC = () => {
  const { addToast } = useApp(); const addressRef = useRef<HTMLInputElement>(null); const [mapKey, setMapKey] = useState(''); const [branches, setBranches] = useState<any[]>([]); const [selected, setSelected] = useState<any>(null); const [inventory, setInventory] = useState<any[]>([]); const [form, setForm] = useState<BranchForm>(blankBranch()); const [editingId, setEditingId] = useState(''); const [search, setSearch] = useState(''); const [typeFilter, setTypeFilter] = useState('all'); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState('');
  const updateForm = (key: keyof BranchForm, value: any) => setForm(current => ({ ...current, [key]: value }));
  const applyPlace = React.useCallback((place: Partial<AddressTarget>) => setForm(current => ({ ...current, ...place })), []);
  usePlacesAutocomplete(addressRef, mapKey, applyPlace);
  const load = async () => { setLoading(true); const [branchResult, key] = await Promise.all([ApiClient.getBranches(), resolveMapKey()]); setMapKey(key); if (!branchResult.success) setError(branchResult.error); else { const list = branchResult.branches || []; setBranches(list); if (!selected || !list.some(branch => branch.id === selected.id)) setSelected(list[0] || null); } setLoading(false); };
  useEffect(() => { void load(); }, []);
  useEffect(() => { if (selected) void ApiClient.getBranchInventory(selected.id).then(result => result.success ? setInventory(result.inventory || []) : setError(result.error)); else setInventory([]); }, [selected]);
  const visible = useMemo(() => branches.filter(branch => { const text = `${branch.name} ${branch.code} ${branch.city} ${branch.address}`.toLowerCase(); return (!search || text.includes(search.toLowerCase())) && (typeFilter === 'all' || branch.branch_type === typeFilter); }), [branches, search, typeFilter]);
  const choose = (branch: any) => { setSelected(branch); setEditingId(branch.id); setForm({ ...blankBranch(), code: branch.code || '', name: branch.name || '', city: branch.city || '', address: branch.address || '', country: branch.country || 'DO', province: branch.province || '', sector: branch.sector || '', postalCode: branch.postal_code || '', phone: branch.phone || '', whatsapp: branch.whatsapp || '', email: branch.email || '', managerName: branch.manager_name || '', managerPhone: branch.manager_phone || '', managerEmail: branch.manager_email || '', branchType: branch.branch_type || 'branch', isHub: !!branch.is_hub, latitude: branch.latitude == null ? null : Number(branch.latitude), longitude: branch.longitude == null ? null : Number(branch.longitude), logo: null }); };
  const useDeviceLocation = () => { if (!navigator.geolocation) { setError('Este dispositivo no ofrece geolocalización.'); return; } navigator.geolocation.getCurrentPosition(position => setForm(current => ({ ...current, latitude: position.coords.latitude, longitude: position.coords.longitude })), positionError => setError(`No fue posible obtener la ubicación: ${positionError.message}`), { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }); };
  const searchLocation = async () => { if (!mapKey) { setError('Google Maps está NO CONFIGURADO en Configuración Global.'); return; } if (!form.address.trim()) return; setSaving(true); try { const result = await geocodeAddress([form.address, form.city, form.province, form.country].filter(Boolean).join(', '), mapKey); setForm(current => ({ ...current, address: result.formattedAddress, latitude: result.latitude, longitude: result.longitude })); setError(''); } catch (reason: any) { setError(reason.message || 'No se encontró una ubicación verificable.'); } finally { setSaving(false); } };
  const save = async (event: React.FormEvent) => { event.preventDefault(); setSaving(true); setError(''); let businessHours: Record<string, string> = {}; try { businessHours = { general: form.businessHours }; } catch { businessHours = {}; } const payload = { ...form, businessHours, logo: form.logo || undefined }; const result = editingId ? await ApiClient.updateBranch(editingId, payload) : await ApiClient.createBranch(payload); setSaving(false); if (!result.success) { setError(result.error); return; } addToast('success', editingId ? 'Sucursal actualizada' : 'Sucursal creada', 'El backend confirmó la persistencia de los datos operativos.'); setEditingId(result.branch.id); setSelected(result.branch); await load(); };
  const logoFile = (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; if (!['image/png', 'image/jpeg', 'image/webp'].includes(file.type) || file.size > 2 * 1024 * 1024) { setError('El logo debe ser PNG, JPG o WebP y pesar menos de 2 MB.'); return; } const reader = new FileReader(); reader.onload = () => updateForm('logo', String(reader.result)); reader.readAsDataURL(file); };
  return <div className="space-y-6">{title(<Building2 className="h-7 w-7 text-indigo-600" />, 'Sucursales y red operativa', 'Administra identidad, responsables, horarios, tipos de punto y ubicación real. La dirección se completa con Google Places cuando está configurado y nunca se inventan coordenadas.')}{errorBox(error)}<div className="grid gap-3 sm:grid-cols-3"><MetricCard title="Puntos activos" value={branches.length} subtitle="Del tenant actual" icon={<Building2 className="h-5 w-5" />} accent="indigo" /><MetricCard title="Con ubicación" value={branches.filter(branch => branch.latitude != null && branch.longitude != null).length} subtitle="Coordenadas guardadas" icon={<MapPin className="h-5 w-5" />} accent="emerald" /><MetricCard title="Paquetes en selección" value={inventory.length} subtitle="Consulta PostgreSQL" icon={<PackageCheck className="h-5 w-5" />} accent="amber" /></div><Card><div className="mb-4 flex items-center justify-between gap-3"><div><h3 className="font-bold">{editingId ? 'Editar punto operativo' : 'Registrar punto operativo'}</h3><p className="mt-1 text-xs text-slate-500">Logo, datos de contacto, gerente y ubicación se guardan en una sola operación.</p></div>{editingId && <Button variant="ghost" size="sm" onClick={() => { setEditingId(''); setForm(blankBranch()); }}>Nueva sucursal</Button>}</div><form onSubmit={save} className="grid gap-4 lg:grid-cols-3"><label className="text-xs font-bold">Código interno<input required value={form.code} disabled={!!editingId} onChange={event => updateForm('code', event.target.value)} className={fieldClass} placeholder="SDQ-02" /></label><label className="text-xs font-bold">Nombre<input required value={form.name} onChange={event => updateForm('name', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Tipo<select value={form.branchType} onChange={event => updateForm('branchType', event.target.value)} className={fieldClass}><option value="branch">Sucursal</option><option value="agency">Agencia</option><option value="warehouse">Warehouse</option><option value="hub">Hub</option><option value="delivery_point">Punto de entrega</option><option value="pickup_point">Punto de recogida</option></select></label><label className="text-xs font-bold lg:col-span-2">Dirección con sugerencias<input ref={addressRef} required value={form.address} onChange={event => updateForm('address', event.target.value)} className={fieldClass} placeholder="Escribe una dirección y selecciona una sugerencia" /></label><div className="flex items-end gap-2"><Button type="button" variant="secondary" size="sm" onClick={() => void searchLocation()} disabled={saving}><Search className="h-4 w-4" />Buscar ubicación</Button><Button type="button" variant="outline" size="sm" onClick={useDeviceLocation}><Crosshair className="h-4 w-4" />Mi ubicación</Button></div><label className="text-xs font-bold">País<input maxLength={2} value={form.country} onChange={event => updateForm('country', event.target.value.toUpperCase())} className={fieldClass} /></label><label className="text-xs font-bold">Provincia / Estado<input value={form.province} onChange={event => updateForm('province', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Ciudad / Municipio<input required value={form.city} onChange={event => updateForm('city', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Sector<input value={form.sector} onChange={event => updateForm('sector', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Código postal<input value={form.postalCode} onChange={event => updateForm('postalCode', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Teléfono<input value={form.phone} onChange={event => updateForm('phone', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">WhatsApp<input value={form.whatsapp} onChange={event => updateForm('whatsapp', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Correo de sucursal<input type="email" value={form.email} onChange={event => updateForm('email', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Gerente responsable<input value={form.managerName} onChange={event => updateForm('managerName', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Teléfono gerente<input value={form.managerPhone} onChange={event => updateForm('managerPhone', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Correo gerente<input type="email" value={form.managerEmail} onChange={event => updateForm('managerEmail', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold lg:col-span-2">Horario<input value={form.businessHours} onChange={event => updateForm('businessHours', event.target.value)} className={fieldClass} placeholder="Lun-Vie 8:00-18:00" /></label><label className="text-xs font-bold">Logo<input type="file" accept="image/png,image/jpeg,image/webp" onChange={logoFile} className={`${fieldClass} p-2`} /><span className="mt-1 block font-normal text-slate-500">PNG, JPG o WebP · máximo 2 MB</span></label><div className="lg:col-span-3 grid gap-4 md:grid-cols-2"><label className="text-xs font-bold">Latitud<input type="number" step="any" value={form.latitude ?? ''} onChange={event => updateForm('latitude', event.target.value === '' ? null : Number(event.target.value))} className={fieldClass} /></label><label className="text-xs font-bold">Longitud<input type="number" step="any" value={form.longitude ?? ''} onChange={event => updateForm('longitude', event.target.value === '' ? null : Number(event.target.value))} className={fieldClass} /></label></div><div className="lg:col-span-3"><MapPreview latitude={form.latitude} longitude={form.longitude} label={form.name || 'Sucursal'} /></div><label className="flex items-center gap-2 text-xs font-bold"><input type="checkbox" checked={form.isHub} onChange={event => updateForm('isHub', event.target.checked)} className="h-4 w-4 accent-indigo-600" />Marcar como hub</label><div className="flex items-center gap-3 lg:col-span-2"><Button type="submit" disabled={saving}>{saving ? 'Guardando…' : editingId ? 'Guardar cambios' : 'Crear sucursal'}</Button><span className="text-xs text-slate-500">{form.latitude != null && form.longitude != null ? 'Ubicación lista para guardar' : 'Sin coordenadas todavía'}</span></div></form></Card><Card><div className="mb-4 flex flex-wrap gap-3"><label className="relative min-w-64 flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-400" /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Buscar sucursal, código, ciudad o dirección" className={`${fieldClass} pl-9`} /></label><select value={typeFilter} onChange={event => setTypeFilter(event.target.value)} className={`${fieldClass} mt-0 w-auto`}><option value="all">Todos los tipos</option><option value="branch">Sucursales</option><option value="agency">Agencias</option><option value="warehouse">Warehouses</option><option value="hub">Hubs</option></select></div><div className="grid gap-3 lg:grid-cols-2">{visible.map(branch => <button key={branch.id} type="button" onClick={() => choose(branch)} className={`rounded-2xl border p-4 text-left transition ${selected?.id === branch.id ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-950/30' : 'border-slate-200 dark:border-slate-800'}`}><div className="flex items-start justify-between gap-3"><div className="flex gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 font-black text-indigo-700">{branch.name?.slice(0, 1).toUpperCase()}</div><div><p className="font-bold">{branch.name}</p><p className="text-xs text-slate-500">{branch.code} · {branch.branch_type || 'branch'} · {branch.city}</p></div></div>{branch.latitude != null && branch.longitude != null ? <CheckCircle2 className="h-5 w-5 text-emerald-600" /> : <AlertTriangle className="h-5 w-5 text-amber-500" />}</div><p className="mt-3 flex gap-1 text-xs text-slate-500"><MapPin className="h-3.5 w-3.5 shrink-0" />{branch.address}</p><p className="mt-2 text-xs text-slate-500">Gerente: {branch.manager_name || 'Sin asignar'} · {branch.logo_url ? 'Logo configurado' : 'Sin logo'}</p></button>)}{!visible.length && <p className="py-8 text-center text-sm text-slate-500 lg:col-span-2">No hay sucursales que coincidan.</p>}</div></Card>{selected && <Card><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="font-bold">Inventario de {selected.name}</h3><p className="text-xs text-slate-500">{selected.address} · {selected.phone || 'Sin teléfono'}</p></div><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold dark:bg-slate-800">{inventory.length} paquetes consultados</span></div></Card>}</div>;
};

export const ProductionClientsAdmin: React.FC = () => {
  const { addToast, setActiveSubView } = useApp(); const [clients, setClients] = useState<any[]>([]); const [branches, setBranches] = useState<any[]>([]); const [q, setQ] = useState(''); const [status, setStatus] = useState('active'); const [tier, setTier] = useState(''); const [branchId, setBranchId] = useState(''); const [balance, setBalance] = useState(''); const [sort, setSort] = useState('created_at'); const [direction, setDirection] = useState('desc'); const [pagination, setPagination] = useState<any>({ page: 1, pages: 1, total: 0 }); const [page, setPage] = useState(1); const [selected, setSelected] = useState<any>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [supporting, setSupporting] = useState('');
  const load = async (nextPage = page) => { setLoading(true); const result = await ApiClient.getClients({ q, status, tier, branchId, balance, sort, direction, page: nextPage, limit: 50 }); if (result.success) { setClients(result.clients || []); setPagination(result.pagination || { page: nextPage, pages: 1, total: result.clients?.length || 0 }); setPage(nextPage); setError(''); } else setError(result.error); setLoading(false); };
  useEffect(() => { void Promise.all([ApiClient.getBranches(), load(1)]).then(([branchResult]) => { if (branchResult.success) setBranches(branchResult.branches || []); }); }, []);
  const apply = (event: React.FormEvent) => { event.preventDefault(); void load(1); };
  const sortBy = (column: string) => { const nextDirection = sort === column && direction === 'desc' ? 'asc' : 'desc'; setSort(column); setDirection(nextDirection); void ApiClient.getClients({ q, status, tier, branchId, balance, sort: column, direction: nextDirection, page: 1, limit: 50 }).then(result => { if (result.success) { setClients(result.clients || []); setPagination(result.pagination); setPage(1); } }); };
  const deactivate = async (client: any) => { if (!window.confirm(`Se quitará el acceso activo de ${client.name}. Sus envíos e historial se conservarán. ¿Continuar?`)) return; const result = await ApiClient.deactivateClient(client.id); if (!result.success) { setError(result.error); return; } addToast('success', 'Cliente desactivado', 'El acceso fue revocado y el historial se conservó.'); void load(page); };
  const support = async (client: any) => { setSupporting(client.id); const result = await ApiClient.startClientSupport(client.id); setSupporting(''); if (!result.success) { setError(result.error); return; } const child = window.open(`/portal/dashboard#support_token=${encodeURIComponent(result.token)}`, '_blank', 'noopener,noreferrer'); if (!child) setError('El navegador bloqueó la ventana de asistencia. Permite ventanas emergentes para continuar.'); else addToast('success', 'Asistencia iniciada', 'Se abrió una sesión temporal de solo lectura para este cliente.'); };
  const exportCsv = () => { const headers = ['Nombre', 'Empresa', 'Correo', 'Teléfono', 'Sucursal', 'Plan', 'Envíos', 'Última actividad']; const lines = [headers, ...clients.map(client => [client.name, client.company_name || '', client.email, client.phone, client.branch_name || '', client.tier || '', client.shipment_count || 0, client.last_activity_at || ''])].map(row => row.map(value => `"${String(value ?? '').replaceAll('"', '""')}"`).join(',')).join('\n'); const url = URL.createObjectURL(new Blob([lines], { type: 'text/csv;charset=utf-8' })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'clientes-gopaq.csv'; anchor.click(); URL.revokeObjectURL(url); };
  return <div className="space-y-6">{title(<Users className="h-7 w-7 text-indigo-600" />, 'Clientes y empresas', 'Directorio avanzado con filtros del servidor, paginación, ordenamiento, estado de acceso, actividad logística y asistencia temporal auditada.')}{errorBox(error)}<Card><form onSubmit={apply} className="grid gap-3 lg:grid-cols-[1.5fr_repeat(4,1fr)_auto]"><label className="relative lg:col-span-2"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-400" /><input value={q} onChange={event => setQ(event.target.value)} className={`${fieldClass} pl-9`} placeholder="Nombre, empresa, email, teléfono o ciudad" /></label><select value={status} onChange={event => setStatus(event.target.value)} className={`${fieldClass} mt-0`}><option value="active">Activos</option><option value="inactive">Inactivos</option><option value="all">Todos</option></select><select value={branchId} onChange={event => setBranchId(event.target.value)} className={`${fieldClass} mt-0`}><option value="">Todas las sucursales</option>{branches.map(branch => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select><select value={tier} onChange={event => setTier(event.target.value)} className={`${fieldClass} mt-0`}><option value="">Todos los planes</option><option value="Standard">Standard</option><option value="Business">Business</option><option value="Enterprise">Enterprise</option></select><select value={balance} onChange={event => setBalance(event.target.value)} className={`${fieldClass} mt-0`}><option value="">Cualquier saldo</option><option value="positive">Con saldo pendiente</option></select><Button type="submit" icon={<Search className="h-4 w-4" />}>Filtrar</Button></form></Card><div className="flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-slate-500">{pagination.total ?? clients.length} resultados · página {pagination.page || page} de {pagination.pages || 1}</p><Button variant="secondary" size="sm" onClick={exportCsv} disabled={!clients.length} icon={<Download className="h-4 w-4" />}>Exportar resultados</Button></div><Card className="overflow-hidden p-0">{loading ? <p className="p-8 text-sm text-slate-500">Consultando clientes…</p> : !clients.length ? <p className="p-8 text-sm text-slate-500">No hay clientes con esos filtros.</p> : <div className="overflow-x-auto"><table className="min-w-[920px] w-full text-left text-xs"><thead className="border-b border-slate-200 bg-slate-50 dark:border-slate-800 dark:bg-slate-950"><tr>{[['name', 'Cliente'], ['email', 'Contacto'], ['created_at', 'Registro'], ['updated_at', 'Actividad']].map(([key, label]) => <th key={key} className="px-4 py-3"><button type="button" onClick={() => sortBy(key)} className="flex items-center gap-1 font-bold uppercase tracking-wide text-slate-500">{label}<ArrowDownUp className="h-3 w-3" /></button></th>)}<th className="px-4 py-3">Sucursal / plan</th><th className="px-4 py-3">Envíos</th><th className="px-4 py-3">Acciones</th></tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-800">{clients.map(client => <tr key={client.id} className="hover:bg-slate-50 dark:hover:bg-slate-950"><td className="px-4 py-4"><button type="button" className="flex items-center gap-3 text-left" onClick={() => setSelected(client)}><span className="flex h-9 w-9 items-center justify-center rounded-full bg-indigo-100 font-black text-indigo-700">{String(client.name || '?').slice(0, 1).toUpperCase()}</span><span><b className="block">{client.company_name || client.name}</b><span className="text-slate-500">{client.name}</span></span></button></td><td className="px-4 py-4"><span>{client.email}</span><br /><span className="text-slate-500">{client.phone}</span></td><td className="px-4 py-4 text-slate-500">{client.created_at ? new Date(client.created_at).toLocaleDateString() : '—'}</td><td className="px-4 py-4 text-slate-500">{client.last_activity_at ? new Date(client.last_activity_at).toLocaleDateString() : 'Sin envíos'}</td><td className="px-4 py-4"><b>{client.branch_name || 'Sin sucursal'}</b><br /><span className="text-slate-500">{client.tier || 'Standard'} · {client.active ? 'Activo' : 'Inactivo'}</span></td><td className="px-4 py-4 font-bold">{client.shipment_count || 0}</td><td className="px-4 py-4"><div className="flex flex-wrap gap-2"><Button variant="outline" size="xs" onClick={() => setSelected(client)} icon={<FileText className="h-3.5 w-3.5" />}>Perfil</Button><Button variant="secondary" size="xs" onClick={() => { setSelected(client); setActiveSubView('envios'); }}>Envíos</Button>{client.has_login ? <Button variant="secondary" size="xs" disabled={supporting === client.id} onClick={() => void support(client)}>{supporting === client.id ? 'Abriendo…' : 'Asistencia'}</Button> : <span className="rounded-md bg-amber-50 px-2 py-1 text-[11px] text-amber-700">Sin acceso</span>}{client.active && <Button variant="danger" size="xs" onClick={() => void deactivate(client)} icon={<Trash2 className="h-3.5 w-3.5" />}>Desactivar</Button>}</div></td></tr>)}</tbody></table></div>}</Card><div className="flex justify-end gap-2"><Button variant="secondary" size="sm" disabled={page <= 1 || loading} onClick={() => void load(page - 1)}>Anterior</Button><Button variant="secondary" size="sm" disabled={page >= (pagination.pages || 1) || loading} onClick={() => void load(page + 1)}>Siguiente</Button></div>{selected && <Card className="border-indigo-200 dark:border-indigo-900"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-widest text-indigo-600">Ficha del cliente</p><h3 className="mt-1 text-xl font-black">{selected.company_name || selected.name}</h3><p className="mt-1 text-sm text-slate-500">{selected.email} · {selected.phone}</p></div><button type="button" onClick={() => setSelected(null)} className="text-slate-400">×</button></div><div className="mt-5 grid gap-3 sm:grid-cols-4"><div><p className="text-xs text-slate-500">Sucursal</p><b>{selected.branch_name || '—'}</b></div><div><p className="text-xs text-slate-500">Plan</p><b>{selected.tier || 'Standard'}</b></div><div><p className="text-xs text-slate-500">Envíos</p><b>{selected.shipment_count || 0}</b></div><div><p className="text-xs text-slate-500">Acceso</p><b>{selected.has_login ? 'Cuenta activa' : 'Sin cuenta'}</b></div></div><p className="mt-4 rounded-xl bg-slate-50 p-3 text-xs leading-5 text-slate-600 dark:bg-slate-950 dark:text-slate-300">La asistencia abre un portal temporal de solo lectura, registra al administrador que la inició y no expone ni cambia la contraseña del cliente.</p></Card>}</div>;
};

type ZoneForm = { name: string; description: string; riskLevel: string; country: string; province: string; city: string; sector: string; latitude: number | null; longitude: number | null; radiusM: string; surchargeAmount: string; restrictionPolicy: string; alertReason: string; polygonGeojson: string };
const blankZone = (): ZoneForm => ({ name: '', description: '', riskLevel: 'moderado', country: 'DO', province: '', city: 'Santo Domingo', sector: '', latitude: null, longitude: null, radiusM: '500', surchargeAmount: '0', restrictionPolicy: 'Revisar con despacho', alertReason: '', polygonGeojson: '' });

export const ProductionDangerZonesAdmin: React.FC = () => {
  const { addToast } = useApp(); const addressRef = useRef<HTMLInputElement>(null); const [mapKey, setMapKey] = useState(''); const [zones, setZones] = useState<any[]>([]); const [form, setForm] = useState<ZoneForm>(blankZone()); const [editingId, setEditingId] = useState(''); const [q, setQ] = useState(''); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const update = (key: keyof ZoneForm, value: any) => setForm(current => ({ ...current, [key]: value })); const applyPlace = React.useCallback((place: Partial<AddressTarget>) => setForm(current => ({ ...current, ...place })), []); usePlacesAutocomplete(addressRef, mapKey, applyPlace);
  const load = async () => { setLoading(true); const [zonesResult, key] = await Promise.all([ApiClient.getDangerousZones({ status: 'active', q }), resolveMapKey()]); setMapKey(key); if (zonesResult.success) setZones(zonesResult.zones || []); else setError(zonesResult.error); setLoading(false); }; useEffect(() => { void load(); }, []);
  const locate = async () => { if (!mapKey || !form.city) { setError('Configura Google Maps y escribe una ciudad para buscar.'); return; } setSaving(true); try { const result = await geocodeAddress([form.sector, form.city, form.province, form.country].filter(Boolean).join(', '), mapKey); setForm(current => ({ ...current, latitude: result.latitude, longitude: result.longitude })); setError(''); } catch (reason: any) { setError(reason.message || 'No se encontró la ubicación.'); } finally { setSaving(false); } };
  const currentLocation = () => { if (!navigator.geolocation) return setError('Este dispositivo no ofrece geolocalización.'); navigator.geolocation.getCurrentPosition(position => setForm(current => ({ ...current, latitude: position.coords.latitude, longitude: position.coords.longitude })), reason => setError(reason.message), { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }); };
  const save = async (event: React.FormEvent) => { event.preventDefault(); setSaving(true); setError(''); const payload = { ...form, radiusM: Number(form.radiusM), surchargeAmount: Number(form.surchargeAmount), polygonGeojson: form.polygonGeojson || undefined }; const result = editingId ? await ApiClient.updateDangerousZone(editingId, payload) : await ApiClient.createDangerousZone(payload); setSaving(false); if (!result.success) { setError(result.error); return; } addToast('success', editingId ? 'Zona actualizada' : 'Zona creada', 'La zona y sus coordenadas quedaron persistidas para los motores operativos.'); setForm(blankZone()); setEditingId(''); void load(); };
  const deactivate = async (zone: any) => { if (!window.confirm(`¿Desactivar la zona ${zone.name}?`)) return; const result = await ApiClient.deactivateDangerousZone(zone.id); if (!result.success) setError(result.error); else { addToast('success', 'Zona desactivada', 'Dejó de estar disponible para nuevas operaciones.'); void load(); } };
  return <div className="space-y-6">{title(<ShieldAlert className="h-7 w-7 text-rose-600" />, 'Zonas peligrosas y geofencing', 'Gestiona puntos de alerta reales con radio de cobertura. También admite un polígono GeoJSON para delimitar áreas y deja el dato disponible para cotización, despacho, COD y rutas.')}{errorBox(error)}<div className="grid gap-3 sm:grid-cols-3"><MetricCard title="Zonas activas" value={zones.length} subtitle="Aplicables al tenant" icon={<ShieldAlert className="h-5 w-5" />} accent="rose" /><MetricCard title="Con coordenadas" value={zones.filter(zone => zone.latitude != null && zone.longitude != null).length} subtitle="PostGIS listo" icon={<MapPin className="h-5 w-5" />} accent="emerald" /><MetricCard title="Radio total" value={`${zones.reduce((sum, zone) => sum + inputNumber(zone.radius_m), 0).toLocaleString()} m`} subtitle="Cobertura configurada" icon={<Crosshair className="h-5 w-5" />} accent="amber" /></div><Card><div className="mb-4 flex items-center justify-between gap-3"><div><h3 className="font-bold">{editingId ? 'Editar zona' : 'Nueva zona de alerta'}</h3><p className="mt-1 text-xs text-slate-500">Para dibujar un polígono, pega el GeoJSON Polygon generado por tu herramienta GIS; el backend valida y guarda el geometry.</p></div>{editingId && <Button variant="ghost" size="sm" onClick={() => { setEditingId(''); setForm(blankZone()); }}>Cancelar edición</Button>}</div><form onSubmit={save} className="grid gap-4 lg:grid-cols-3"><label className="text-xs font-bold">Nombre<input required value={form.name} onChange={event => update('name', event.target.value)} className={fieldClass} placeholder="Sector con restricción" /></label><label className="text-xs font-bold">Nivel<select value={form.riskLevel} onChange={event => update('riskLevel', event.target.value)} className={fieldClass}><option value="bajo">🟢 Bajo</option><option value="moderado">🟡 Moderado</option><option value="alto">🟠 Alto</option><option value="critico">🔴 Crítico</option></select></label><label className="text-xs font-bold">Ciudad<input required value={form.city} onChange={event => update('city', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold lg:col-span-2">Buscar dirección / sector<input ref={addressRef} value={form.sector} onChange={event => update('sector', event.target.value)} className={fieldClass} placeholder="Escribe y selecciona una sugerencia" /></label><div className="flex items-end gap-2"><Button type="button" variant="secondary" size="sm" onClick={() => void locate()} disabled={saving}><Search className="h-4 w-4" />Buscar</Button><Button type="button" variant="outline" size="sm" onClick={currentLocation}><Crosshair className="h-4 w-4" />GPS</Button></div><label className="text-xs font-bold">Provincia<input value={form.province} onChange={event => update('province', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">País<input maxLength={2} value={form.country} onChange={event => update('country', event.target.value.toUpperCase())} className={fieldClass} /></label><label className="text-xs font-bold">Radio (metros)<input required type="number" min="25" value={form.radiusM} onChange={event => update('radiusM', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Recargo (DOP)<input type="number" min="0" step="0.01" value={form.surchargeAmount} onChange={event => update('surchargeAmount', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Política<input required value={form.restrictionPolicy} onChange={event => update('restrictionPolicy', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold lg:col-span-3">Descripción<textarea value={form.description} onChange={event => update('description', event.target.value)} className={`${fieldClass} min-h-20`} /></label><label className="text-xs font-bold lg:col-span-3">Motivo de alerta<textarea value={form.alertReason} onChange={event => update('alertReason', event.target.value)} className={`${fieldClass} min-h-20`} /></label><label className="text-xs font-bold lg:col-span-3">Polígono GeoJSON opcional<textarea value={form.polygonGeojson} onChange={event => update('polygonGeojson', event.target.value)} className={`${fieldClass} min-h-24 font-mono text-xs`} placeholder='{"type":"Polygon","coordinates":[...]}' /></label><div className="lg:col-span-3 grid gap-4 md:grid-cols-2"><label className="text-xs font-bold">Latitud<input required type="number" step="any" value={form.latitude ?? ''} onChange={event => update('latitude', event.target.value === '' ? null : Number(event.target.value))} className={fieldClass} /></label><label className="text-xs font-bold">Longitud<input required type="number" step="any" value={form.longitude ?? ''} onChange={event => update('longitude', event.target.value === '' ? null : Number(event.target.value))} className={fieldClass} /></label></div><div className="lg:col-span-3"><MapPreview latitude={form.latitude} longitude={form.longitude} label={form.name || 'Zona peligrosa'} /></div><div className="lg:col-span-3"><Button type="submit" disabled={saving}>{saving ? 'Guardando…' : editingId ? 'Guardar cambios' : 'Crear zona'}</Button></div></form></Card><Card><div className="mb-4 flex gap-3"><label className="relative flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-400" /><input value={q} onChange={event => setQ(event.target.value)} onKeyDown={event => { if (event.key === 'Enter') void load(); }} className={`${fieldClass} pl-9`} placeholder="Buscar zona, ciudad o sector" /></label><Button variant="secondary" onClick={() => void load()}>Buscar</Button></div><div className="grid gap-3 lg:grid-cols-2">{zones.map(zone => <div key={zone.id} className="rounded-2xl border border-slate-200 p-4 dark:border-slate-800"><div className="flex items-start justify-between gap-3"><div><p className="font-bold">{zone.name}</p><p className="mt-1 text-xs text-slate-500">{zone.city} · {zone.sector || 'Sector no indicado'} · {zone.risk_level}</p></div><span className="rounded-full bg-rose-50 px-2 py-1 text-[10px] font-bold text-rose-700">{zone.radius_m} m</span></div><p className="mt-3 text-xs text-slate-500">{zone.latitude != null ? `${Number(zone.latitude).toFixed(6)}, ${Number(zone.longitude).toFixed(6)}` : 'Sin coordenadas'} · Recargo {zone.surcharge_amount || 0}</p><div className="mt-4 flex gap-2"><Button variant="secondary" size="xs" onClick={() => { setEditingId(zone.id); setForm({ ...blankZone(), name: zone.name, description: zone.description || '', riskLevel: zone.risk_level, country: zone.country || 'DO', province: zone.province || '', city: zone.city, sector: zone.sector || '', latitude: zone.latitude == null ? null : Number(zone.latitude), longitude: zone.longitude == null ? null : Number(zone.longitude), radiusM: String(zone.radius_m || 500), surchargeAmount: String(zone.surcharge_amount || 0), restrictionPolicy: zone.restriction_policy, alertReason: zone.alert_reason || '', polygonGeojson: zone.polygon_geojson || '' }); }} icon={<Pencil className="h-3.5 w-3.5" />}>Editar</Button><Button variant="danger" size="xs" onClick={() => void deactivate(zone)} icon={<Trash2 className="h-3.5 w-3.5" />}>Desactivar</Button></div></div>)}{!zones.length && !loading && <p className="py-8 text-center text-sm text-slate-500 lg:col-span-2">No hay zonas activas.</p>}</div></Card></div>;
};

type Tier = { min: string; max: string; price: string; additionalRate: string };
type RateForm = { ruleCode: string; serviceType: string; serviceVariant: string; originZone: string; destZone: string; baseRate: string; perKgRate: string; perVolRate: string; minCharge: string; maxWeight: string; pricingMode: string; weightUnit: string; includedWeight: string; additionalWeightStep: string; additionalWeightRate: string; includedDistanceKm: string; distanceRate: string; currency: string; priority: string; clientId: string; branchId: string; tiers: Tier[]; surcharges: { name: string; type: string; value: string }[] };
const blankRate = (): RateForm => ({ ruleCode: '', serviceType: 'local', serviceVariant: '', originZone: '*', destZone: '*', baseRate: '150', perKgRate: '40', perVolRate: '40', minCharge: '150', maxWeight: '', pricingMode: 'hybrid', weightUnit: 'lb', includedWeight: '1', additionalWeightStep: '1', additionalWeightRate: '50', includedDistanceKm: '3', distanceRate: '25', currency: 'DOP', priority: '100', clientId: '', branchId: '', tiers: [], surcharges: [] });

export const ProductionRatesAdmin: React.FC = () => {
  const { addToast, formatMoney } = useApp(); const [rates, setRates] = useState<any[]>([]); const [branches, setBranches] = useState<any[]>([]); const [form, setForm] = useState<RateForm>(blankRate()); const [editingId, setEditingId] = useState(''); const [serviceFilter, setServiceFilter] = useState(''); const [sim, setSim] = useState({ originCity: 'Santo Domingo', destCity: 'Santo Domingo', weightKg: '1', lengthCm: '20', widthCm: '15', heightCm: '10', distanceKm: '3', clientId: '', branchId: '', codAmount: '0' }); const [quote, setQuote] = useState<any>(null); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const update = (key: keyof RateForm, value: any) => setForm(current => ({ ...current, [key]: value })); const load = async () => { setLoading(true); const [rateResult, branchResult] = await Promise.all([ApiClient.getRates(serviceFilter ? { serviceType: serviceFilter } : undefined), ApiClient.getBranches()]); if (rateResult.success) setRates(rateResult.rates || []); else setError(rateResult.error); if (branchResult.success) setBranches(branchResult.branches || []); setLoading(false); }; useEffect(() => { void load(); }, [serviceFilter]);
  const payload = () => ({ ruleCode: form.ruleCode || undefined, serviceType: form.serviceType, serviceVariant: form.serviceVariant || undefined, originZone: form.originZone || '*', destZone: form.destZone || '*', baseRate: Number(form.baseRate), perKgRate: Number(form.perKgRate), perVolRate: Number(form.perVolRate), minCharge: Number(form.minCharge), maxWeight: form.maxWeight ? Number(form.maxWeight) : null, pricingMode: form.pricingMode, weightUnit: form.weightUnit, includedWeight: Number(form.includedWeight), additionalWeightStep: Number(form.additionalWeightStep), additionalWeightRate: Number(form.additionalWeightRate), includedDistanceKm: Number(form.includedDistanceKm), distanceRate: Number(form.distanceRate), currency: form.currency, priority: Number(form.priority), clientId: form.clientId || null, branchId: form.branchId || null, tiers: form.tiers.map(tier => ({ min: Number(tier.min), max: Number(tier.max), price: Number(tier.price), additionalRate: tier.additionalRate ? Number(tier.additionalRate) : undefined })), surcharges: Object.fromEntries(form.surcharges.filter(item => item.name.trim()).map(item => [item.name.trim(), { type: item.type, value: Number(item.value) }])) });
  const save = async (event: React.FormEvent) => { event.preventDefault(); setSaving(true); setError(''); const result = editingId ? await ApiClient.updateRate(editingId, payload()) : await ApiClient.createRate(payload()); setSaving(false); if (!result.success) { setError(result.error); return; } addToast('success', editingId ? 'Tarifa actualizada' : 'Tarifa creada', 'La regla quedó disponible para el motor central de precios.'); setForm(blankRate()); setEditingId(''); void load(); };
  const simulate = async (event: React.FormEvent) => { event.preventDefault(); setSaving(true); setError(''); const result = await ApiClient.simulateRate({ serviceType: form.serviceType, ...sim, weightKg: Number(sim.weightKg), lengthCm: Number(sim.lengthCm), widthCm: Number(sim.widthCm), heightCm: Number(sim.heightCm), distanceKm: Number(sim.distanceKm), codAmount: Number(sim.codAmount), clientId: sim.clientId || undefined, branchId: sim.branchId || undefined }); setSaving(false); if (!result.success) { setError(result.error); setQuote(null); return; } setQuote(result.quote); };
  const deactivate = async (rate: any) => { if (!window.confirm(`¿Desactivar la regla ${rate.rule_code || rate.ruleCode}?`)) return; const result = await ApiClient.deactivateRate(rate.id); if (!result.success) setError(result.error); else { addToast('success', 'Tarifa desactivada', 'Dejó de aplicar a nuevas cotizaciones.'); void load(); } };
  const edit = (rate: any) => setForm({ ...blankRate(), ruleCode: rate.rule_code || '', serviceType: rate.service_type, serviceVariant: rate.service_variant || '', originZone: rate.origin_zone || '*', destZone: rate.dest_zone || '*', baseRate: String(rate.base_rate ?? 0), perKgRate: String(rate.per_kg_rate ?? 0), perVolRate: String(rate.per_vol_rate ?? 0), minCharge: String(rate.min_charge ?? 0), maxWeight: rate.max_weight == null ? '' : String(rate.max_weight), pricingMode: rate.pricing_mode || 'base_plus_weight', weightUnit: rate.weight_unit || 'kg', includedWeight: String(rate.included_weight ?? 1), additionalWeightStep: String(rate.additional_weight_step ?? 1), additionalWeightRate: String(rate.additional_weight_rate ?? rate.per_kg_rate ?? 0), includedDistanceKm: String(rate.included_distance_km ?? 0), distanceRate: String(rate.distance_rate ?? 0), currency: rate.currency || 'DOP', priority: String(rate.priority ?? 100), clientId: rate.client_id || '', branchId: rate.branch_id || '', tiers: (rate.tiers || []).map((tier: any) => ({ min: String(tier.min), max: String(tier.max), price: String(tier.price), additionalRate: tier.additionalRate == null ? '' : String(tier.additionalRate) })), surcharges: Object.entries(rate.surcharges || {}).map(([name, surcharge]: [string, any]) => ({ name, type: surcharge.type, value: String(surcharge.value) })) });
  const setTier = (index: number, key: keyof Tier, value: string) => setForm(current => ({ ...current, tiers: current.tiers.map((tier, position) => position === index ? { ...tier, [key]: value } : tier) }));
  return <div className="space-y-6">{title(<SlidersHorizontal className="h-7 w-7 text-indigo-600" />, 'Motor central de tarifas', 'Configura reglas por servicio, zona, cliente o sucursal. Soporta fijo, kilómetros, peso, libra, escalones, volumen, recargos y un simulador que muestra la regla aplicada por el backend.')}{errorBox(error)}<div className="grid gap-3 sm:grid-cols-4"><MetricCard title="Reglas activas" value={rates.length} subtitle="Filtradas desde PostgreSQL" icon={<SlidersHorizontal className="h-5 w-5" />} accent="indigo" /><MetricCard title="Servicios" value={new Set(rates.map(rate => rate.service_type)).size} subtitle="Local, nacional, internacional…" icon={<PackageCheck className="h-5 w-5" />} accent="emerald" /><MetricCard title="Por libra" value={rates.filter(rate => rate.weight_unit === 'lb').length} subtitle="Reglas con unidad lb" icon={<ArrowDownUp className="h-5 w-5" />} accent="amber" /><MetricCard title="Simulador" value={quote ? formatMoney(inputNumber(quote.total), quote.currency) : 'Listo'} subtitle="Sin precio local inventado" icon={<BarChart3 className="h-5 w-5" />} accent="purple" /></div><Card><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h3 className="font-bold">{editingId ? 'Editar regla tarifaria' : 'Nueva regla tarifaria'}</h3><p className="mt-1 text-xs text-slate-500">La prioridad menor se evalúa primero; una regla específica puede superar a la general.</p></div>{editingId && <Button variant="ghost" size="sm" onClick={() => { setEditingId(''); setForm(blankRate()); }}>Cancelar edición</Button>}</div><form onSubmit={save} className="grid gap-4 lg:grid-cols-4"><label className="text-xs font-bold">Código de regla<input value={form.ruleCode} onChange={event => update('ruleCode', event.target.value)} className={fieldClass} placeholder="TARIFA-NACIONAL-023" /></label><label className="text-xs font-bold">Servicio<select value={form.serviceType} onChange={event => update('serviceType', event.target.value)} className={fieldClass}><option value="local">Local / última milla</option><option value="express">Express</option><option value="nacional">Nacional</option><option value="internacional">Internacional</option><option value="mudanza">Mudanza</option><option value="carga_pesada">Carga pesada</option></select></label><label className="text-xs font-bold">Variante<select value={form.serviceVariant} onChange={event => update('serviceVariant', event.target.value)} className={fieldClass}><option value="">General</option><option value="standard">Standard</option><option value="economy">Economy</option><option value="express">Express</option><option value="aereo">Aéreo</option><option value="maritimo">Marítimo</option></select></label><label className="text-xs font-bold">Prioridad<input type="number" min="1" value={form.priority} onChange={event => update('priority', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Zona / origen<input value={form.originZone} onChange={event => update('originZone', event.target.value)} className={fieldClass} placeholder="* o Santo Domingo" /></label><label className="text-xs font-bold">Zona / destino<input value={form.destZone} onChange={event => update('destZone', event.target.value)} className={fieldClass} placeholder="* o Santiago" /></label><label className="text-xs font-bold">Cliente específico<select value={form.clientId} onChange={event => update('clientId', event.target.value)} className={fieldClass}><option value="">Todos los clientes</option></select><span className="mt-1 block font-normal text-slate-400">Se puede completar con el ID desde la ficha contractual.</span></label><label className="text-xs font-bold">Sucursal específica<select value={form.branchId} onChange={event => update('branchId', event.target.value)} className={fieldClass}><option value="">Todas las sucursales</option>{branches.map(branch => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select></label><label className="text-xs font-bold">Modelo<select value={form.pricingMode} onChange={event => update('pricingMode', event.target.value)} className={fieldClass}><option value="flat">Tarifa fija</option><option value="per_km">Solo por kilómetros</option><option value="base_plus_km">Base + kilómetros</option><option value="base_plus_weight">Base + peso</option><option value="hybrid">Híbrida: base + km + peso</option><option value="tiered">Escalonada por rangos</option></select></label><label className="text-xs font-bold">Moneda<select value={form.currency} onChange={event => update('currency', event.target.value)} className={fieldClass}><option value="DOP">DOP</option><option value="USD">USD</option><option value="EUR">EUR</option></select></label><label className="text-xs font-bold">Tarifa base<input type="number" min="0" step="0.01" required value={form.baseRate} onChange={event => update('baseRate', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Mínimo facturable<input type="number" min="0" step="0.01" required value={form.minCharge} onChange={event => update('minCharge', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Unidad de peso<select value={form.weightUnit} onChange={event => update('weightUnit', event.target.value)} className={fieldClass}><option value="lb">Libra (lb)</option><option value="kg">Kilogramo (kg)</option></select></label><label className="text-xs font-bold">Peso incluido<input type="number" min="0" step="0.01" value={form.includedWeight} onChange={event => update('includedWeight', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Paso adicional<input type="number" min="0.01" step="0.01" value={form.additionalWeightStep} onChange={event => update('additionalWeightStep', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Precio peso adicional<input type="number" min="0" step="0.01" value={form.additionalWeightRate} onChange={event => update('additionalWeightRate', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Km incluidos<input type="number" min="0" step="0.01" value={form.includedDistanceKm} onChange={event => update('includedDistanceKm', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Precio por km adicional<input type="number" min="0" step="0.01" value={form.distanceRate} onChange={event => update('distanceRate', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Precio por kg legado / volumen<input type="number" min="0" step="0.01" value={form.perKgRate} onChange={event => update('perKgRate', event.target.value)} className={fieldClass} /></label><label className="text-xs font-bold">Precio volumétrico<input type="number" min="0" step="0.01" value={form.perVolRate} onChange={event => update('perVolRate', event.target.value)} className={fieldClass} /></label><div className="rounded-xl border border-slate-200 p-3 lg:col-span-4 dark:border-slate-800"><div className="flex items-center justify-between"><div><h4 className="text-xs font-bold">Rangos por libra / peso</h4><p className="text-[11px] text-slate-500">Usa el modelo escalonado para 0-5, 6-10, 11-20 lb, etc.</p></div><Button type="button" variant="secondary" size="xs" onClick={() => setForm(current => ({ ...current, tiers: [...current.tiers, { min: '0', max: '5', price: '250', additionalRate: '' }] }))} icon={<Plus className="h-3 w-3" />}>Añadir rango</Button></div>{form.tiers.map((tier, index) => <div key={index} className="mt-3 grid gap-2 sm:grid-cols-4"><input type="number" min="0" value={tier.min} onChange={event => setTier(index, 'min', event.target.value)} className={fieldClass} placeholder="Desde" /><input type="number" min="0" value={tier.max} onChange={event => setTier(index, 'max', event.target.value)} className={fieldClass} placeholder="Hasta" /><input type="number" min="0" value={tier.price} onChange={event => setTier(index, 'price', event.target.value)} className={fieldClass} placeholder="Precio tramo" /><div className="flex gap-2"><input type="number" min="0" value={tier.additionalRate} onChange={event => setTier(index, 'additionalRate', event.target.value)} className={fieldClass} placeholder="Adicional" /><Button type="button" variant="danger" size="xs" onClick={() => setForm(current => ({ ...current, tiers: current.tiers.filter((_, position) => position !== index) }))}><Trash2 className="h-3.5 w-3.5" /></Button></div></div>)}</div><div className="rounded-xl border border-slate-200 p-3 lg:col-span-4 dark:border-slate-800"><div className="flex items-center justify-between"><div><h4 className="text-xs font-bold">Recargos configurables</h4><p className="text-[11px] text-slate-500">Combustible, zona peligrosa, noche, domingo, COD, seguro o manejo especial.</p></div><Button type="button" variant="secondary" size="xs" onClick={() => setForm(current => ({ ...current, surcharges: [...current.surcharges, { name: '', type: 'fixed', value: '0' }] }))} icon={<Plus className="h-3 w-3" />}>Añadir recargo</Button></div>{form.surcharges.map((surcharge, index) => <div key={index} className="mt-3 grid gap-2 sm:grid-cols-4"><input value={surcharge.name} onChange={event => setForm(current => ({ ...current, surcharges: current.surcharges.map((item, position) => position === index ? { ...item, name: event.target.value } : item) }))} className={fieldClass} placeholder="Zona peligrosa" /><select value={surcharge.type} onChange={event => setForm(current => ({ ...current, surcharges: current.surcharges.map((item, position) => position === index ? { ...item, type: event.target.value } : item) }))} className={fieldClass}><option value="fixed">Valor fijo</option><option value="percent">Porcentaje</option><option value="unit">Por unidad</option></select><input type="number" min="0" value={surcharge.value} onChange={event => setForm(current => ({ ...current, surcharges: current.surcharges.map((item, position) => position === index ? { ...item, value: event.target.value } : item) }))} className={fieldClass} placeholder="Valor" /><Button type="button" variant="danger" size="xs" onClick={() => setForm(current => ({ ...current, surcharges: current.surcharges.filter((_, position) => position !== index) }))}><Trash2 className="h-3.5 w-3.5" /></Button></div>)}</div><div className="lg:col-span-4"><Button type="submit" disabled={saving}>{saving ? 'Guardando regla…' : editingId ? 'Guardar regla' : 'Crear regla'}</Button></div></form></Card><Card><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h3 className="font-bold">Reglas guardadas</h3><p className="text-xs text-slate-500">Cada registro se puede editar o desactivar; el cotizador solo usa reglas activas.</p></div><select value={serviceFilter} onChange={event => { setServiceFilter(event.target.value); setTimeout(() => void load(), 0); }} className={`${fieldClass} mt-0 w-auto`}><option value="">Todos los servicios</option><option value="local">Local</option><option value="nacional">Nacional</option><option value="internacional">Internacional</option><option value="mudanza">Mudanza</option><option value="carga_pesada">Carga pesada</option></select></div><div className="grid gap-3 lg:grid-cols-2">{rates.map(rate => <div key={rate.id} className="rounded-2xl border border-slate-200 p-4 dark:border-slate-800"><div className="flex items-start justify-between gap-3"><div><p className="font-mono text-xs font-bold text-indigo-600">{rate.rule_code || rate.id}</p><p className="mt-1 font-bold">{rate.service_type} · {rate.pricing_mode}</p></div><span className="rounded-full bg-emerald-50 px-2 py-1 text-[10px] font-bold text-emerald-700">Prioridad {rate.priority}</span></div><p className="mt-3 text-xs text-slate-500">Base {rate.base_rate} {rate.currency} · {rate.weight_unit} · adicional {rate.additional_weight_rate ?? rate.per_kg_rate} · km {rate.distance_rate || 0}</p><p className="mt-1 text-xs text-slate-500">{rate.origin_zone} → {rate.dest_zone} · {rate.tiers?.length || 0} rangos · {Object.keys(rate.surcharges || {}).length} recargos</p><div className="mt-4 flex gap-2"><Button variant="secondary" size="xs" onClick={() => { setEditingId(rate.id); edit(rate); }} icon={<Pencil className="h-3.5 w-3.5" />}>Editar</Button><Button variant="danger" size="xs" onClick={() => void deactivate(rate)} icon={<Trash2 className="h-3.5 w-3.5" />}>Desactivar</Button></div></div>)}{!rates.length && !loading && <p className="py-8 text-center text-sm text-slate-500 lg:col-span-2">No hay reglas tarifarias activas.</p>}</div></Card><Card className="border-indigo-200 dark:border-indigo-900"><div className="mb-4 flex items-center gap-3"><BarChart3 className="h-5 w-5 text-indigo-600" /><div><h3 className="font-bold">Simular tarifa</h3><p className="text-xs text-slate-500">La simulación usa el mismo motor central, la organización actual y una regla persistida. No calcula en React.</p></div></div><form onSubmit={simulate} className="grid gap-3 sm:grid-cols-3"><input value={sim.originCity} onChange={event => setSim(current => ({ ...current, originCity: event.target.value }))} className={fieldClass} placeholder="Origen" /><input value={sim.destCity} onChange={event => setSim(current => ({ ...current, destCity: event.target.value }))} className={fieldClass} placeholder="Destino" /><input type="number" min="0.1" value={sim.weightKg} onChange={event => setSim(current => ({ ...current, weightKg: event.target.value }))} className={fieldClass} placeholder="Peso kg" /><input type="number" min="1" value={sim.lengthCm} onChange={event => setSim(current => ({ ...current, lengthCm: event.target.value }))} className={fieldClass} placeholder="Largo cm" /><input type="number" min="1" value={sim.widthCm} onChange={event => setSim(current => ({ ...current, widthCm: event.target.value }))} className={fieldClass} placeholder="Ancho cm" /><input type="number" min="1" value={sim.heightCm} onChange={event => setSim(current => ({ ...current, heightCm: event.target.value }))} className={fieldClass} placeholder="Alto cm" /><input type="number" min="0" value={sim.distanceKm} onChange={event => setSim(current => ({ ...current, distanceKm: event.target.value }))} className={fieldClass} placeholder="Distancia km" /><input type="number" min="0" value={sim.codAmount} onChange={event => setSim(current => ({ ...current, codAmount: event.target.value }))} className={fieldClass} placeholder="COD" /><Button type="submit" disabled={saving}>Simular con API</Button></form>{quote && <div className="mt-5 grid gap-3 rounded-2xl bg-slate-950 p-5 text-white sm:grid-cols-3"><div><p className="text-xs text-slate-400">Regla utilizada</p><p className="mt-1 font-mono font-bold text-orange-300">{quote.ruleCode || '—'}</p></div><div><p className="text-xs text-slate-400">Peso facturable</p><p className="mt-1 font-bold">{quote.billableWeightKg} kg</p></div><div><p className="text-xs text-slate-400">Total</p><p className="mt-1 text-2xl font-black">{formatMoney(inputNumber(quote.total), quote.currency)}</p></div><div className="sm:col-span-3 grid gap-2 border-t border-slate-800 pt-3 text-xs text-slate-300 sm:grid-cols-3"><span>Base: {quote.baseRate}</span><span>Peso: {quote.weightCost}</span><span>Distancia: {quote.distanceCost || 0}</span><span>Recargos: {(quote.dangerousZoneSurcharge || 0) + (quote.configurableSurcharge || 0)}</span><span>Impuestos: {quote.tax}</span><span>Subtotal: {quote.subtotal}</span></div></div>}</Card></div>;
};
